    internal class DetailKindConverter : JsonConverter<DetailKind>
    {
        public override bool CanConvert(Type t) => t == typeof(DetailKind);

        public override DetailKind Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            var value = reader.GetString();
            switch (value)
            {
                case "compatibility":
                    return DetailKind.Compatibility;
                case "deadline":
                    return DetailKind.Deadline;
                case "lifecycle":
                    return DetailKind.Lifecycle;
                case "payloadLimit":
                    return DetailKind.PayloadLimit;
                case "quotationDraftValidation":
                    return DetailKind.QuotationDraftValidation;
                case "revisionConflict":
                    return DetailKind.RevisionConflict;
                case "validation":
                    return DetailKind.Validation;
            }
            throw new Exception("Cannot unmarshal type DetailKind");
        }

        public override void Write(Utf8JsonWriter writer, DetailKind value, JsonSerializerOptions options)
        {
            switch (value)
            {
                case DetailKind.Compatibility:
                    JsonSerializer.Serialize(writer, "compatibility", options);
                    return;
                case DetailKind.Deadline:
                    JsonSerializer.Serialize(writer, "deadline", options);
                    return;
                case DetailKind.Lifecycle:
                    JsonSerializer.Serialize(writer, "lifecycle", options);
                    return;
                case DetailKind.PayloadLimit:
                    JsonSerializer.Serialize(writer, "payloadLimit", options);
                    return;
                case DetailKind.QuotationDraftValidation:
                    JsonSerializer.Serialize(writer, "quotationDraftValidation", options);
                    return;
                case DetailKind.RevisionConflict:
                    JsonSerializer.Serialize(writer, "revisionConflict", options);
                    return;
                case DetailKind.Validation:
                    JsonSerializer.Serialize(writer, "validation", options);
                    return;
            }
            throw new Exception("Cannot marshal type DetailKind");
        }

        public static readonly DetailKindConverter Singleton = new DetailKindConverter();
    }

    internal class QuotationFieldConverter : JsonConverter<QuotationField>
    {
        public override bool CanConvert(Type t) => t == typeof(QuotationField);

        public override QuotationField Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            var value = reader.GetString();
            switch (value)
            {
                case "colorId":
                    return QuotationField.ColorId;
                case "customer":
                    return QuotationField.Customer;
                case "customerRevision":
                    return QuotationField.CustomerRevision;
                case "dimensions":
